//! Differential test: openjd writes a float as CPython's `repr(float)` does.
//!
//! Expression Language §1.3.4 writes a float as the shortest decimal string
//! that reads back as the same binary value, which is CPython's `repr`. The
//! expected text comes from `data/float_repr_cpython.txt`, generated by
//! `scripts/generate_float_repr_fixture.py` with CPython and checked in, so
//! these tests do not run Python.
//!
//! The fixture's optional third column is an intended difference from `repr`.
//! There is exactly one: the expression language normalizes -0.0 to 0.0, so
//! openjd writes `0.0` where `repr` writes `-0.0`.

use openjd_expr::value::{format_float, Float64};
use openjd_expr::{ExprValue, ParsedExpression, SymbolTable};

const FIXTURE: &str = include_str!("data/float_repr_cpython.txt");

/// One fixture line: the double, CPython's `repr`, and the text openjd writes.
pub struct ReprCase {
    pub value: f64,
    pub repr: &'static str,
    pub openjd: &'static str,
}

/// Parse the fixture. Panics on a malformed line, so a damaged fixture fails
/// the tests rather than silently testing less.
pub fn repr_cases() -> Vec<ReprCase> {
    FIXTURE
        .lines()
        .filter(|line| !line.starts_with('#') && !line.is_empty())
        .map(|line| {
            let fields: Vec<&str> = line.split(' ').collect();
            let (bits, repr, openjd) = match fields[..] {
                [bits, repr] => (bits, repr, repr),
                [bits, repr, openjd] => (bits, repr, openjd),
                _ => panic!("malformed fixture line: {line:?}"),
            };
            let bits = u64::from_str_radix(bits, 16).expect("hex bits");
            ReprCase {
                value: f64::from_bits(bits),
                repr,
                openjd,
            }
        })
        .collect()
}

#[test]
fn fixture_covers_the_cases_it_names() {
    let cases = repr_cases();
    assert!(cases.len() > 5000, "{} cases", cases.len());
    let has = |repr: &str| cases.iter().any(|c| c.repr == repr);
    for repr in [
        "2.0",
        "1e+20",
        "1e+16",
        "1000000000000000.0",
        "9999999999999998.0",
        "1e+17",
        "0.0001",
        "1e-05",
        "5e-324",
        "2.2250738585072014e-308",
        "1.7976931348623157e+308",
        "-1.7976931348623157e+308",
        "0.1",
        "-0.0",
    ] {
        assert!(has(repr), "fixture lacks {repr}");
    }
}

#[test]
fn the_only_intended_difference_is_negative_zero() {
    let differences: Vec<(&str, &str)> = repr_cases()
        .into_iter()
        .filter(|c| c.openjd != c.repr)
        .map(|c| (c.repr, c.openjd))
        .collect();
    assert_eq!(differences, [("-0.0", "0.0")]);
}

#[test]
fn format_float_matches_cpython_repr() {
    let mismatches: Vec<String> = repr_cases()
        .iter()
        .filter_map(|c| {
            let got = format_float(c.value);
            // `Float64::display_len` bounds a rendering at 32 bytes.
            assert!(got.len() <= 32, "{got}");
            (got != c.openjd).then(|| format!("{:?}: got {got}, want {}", c.value, c.openjd))
        })
        .collect();
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

#[test]
fn fixture_repr_reads_back_as_the_same_double() {
    // Guards the fixture itself, and Rust's parser, against a text that does
    // not round-trip.
    for c in repr_cases() {
        assert_eq!(
            c.repr.parse::<f64>().unwrap().to_bits(),
            c.value.to_bits(),
            "{}",
            c.repr
        );
    }
}

#[test]
fn computed_float_value_writes_as_cpython_repr() {
    for c in repr_cases() {
        let v = ExprValue::Float(Float64::new(c.value).unwrap());
        assert_eq!(v.to_display_string(), c.openjd, "{:?}", c.value);
    }
}

#[test]
fn computed_float_in_an_expression_writes_as_cpython_repr() {
    // `x * 1.0` computes a float from a bound value, the path a template's
    // `{{Param.X * 1.0}}` takes. Multiplying by 1.0 is exact, and -0.0 * 1.0
    // is -0.0, so this also covers a computed negative zero.
    let expr = ParsedExpression::new("X * 1.0").unwrap();
    let mut mismatches = Vec::new();
    for c in repr_cases() {
        let mut st = SymbolTable::new();
        st.set("X", ExprValue::Float(Float64::new(c.value).unwrap()))
            .unwrap();
        let got = expr.evaluate(&st).unwrap().to_display_string();
        if got != c.openjd {
            mismatches.push(format!("{:?}: got {got}, want {}", c.value, c.openjd));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

#[test]
fn computed_negative_zero_writes_as_zero() {
    let expr = ParsedExpression::new("0.0 * -1.0").unwrap();
    let got = expr.evaluate(&SymbolTable::new()).unwrap();
    assert_eq!(got.to_display_string(), "0.0");
}

#[test]
fn float_list_items_write_as_cpython_repr() {
    let cases = repr_cases();
    let items: Vec<Float64> = cases
        .iter()
        .map(|c| Float64::new(c.value).unwrap())
        .collect();
    let list = ExprValue::make_list(
        items.into_iter().map(ExprValue::Float).collect(),
        openjd_expr::ExprType::FLOAT,
    )
    .unwrap();
    let want = format!(
        "[{}]",
        cases
            .iter()
            .map(|c| c.openjd)
            .collect::<Vec<_>>()
            .join(", ")
    );
    assert_eq!(list.to_display_string(), want);
}
